/*
 * A021063  Decimal expansion of 1/59.
 * https://oeis.org/A021063
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cons, easy
 * Formula:   a(n) = the n-th decimal digit of 1/59 (a(0) = the first digit
 *            after the point). The digits are generated by the standard
 *            long‑division algorithm
 * Range:     u8 n <= 98, u16 n <= 98, u32 n <= 98, u64 n <= 98, u128 n <= 98,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    /* remainder after k divisions; starts with 1 (the numerator of 1/59) */
    uint64_t rem = 1 % 59;
    seq_t digit = 0;

    /* Perform (n+1) division steps to obtain the digit at position n */
    for (idx_t i = 0; i <= n; ++i) {
        uint64_t tmp = rem * 10ULL;      /* next dividend */
        digit = tmp / 59ULL;             /* next decimal digit   */
        rem   = tmp % 59ULL;             /* new remainder        */
    }

    return digit;
}
